const finite=(x,min,max,def)=>Number.isFinite(Number(x))?Math.max(min,Math.min(max,Number(x))):def;
export function normalizeBusiness(raw={}){const catalog=(Array.isArray(raw?.catalog)?raw.catalog:[]).slice(0,300).filter(x=>x&&typeof x.id==='string').map(x=>({id:x.id.slice(0,80),sku:String(x.sku||'').slice(0,80),name:String(x.name||'Материал').slice(0,100),category:['body','front','top','hardware','labor'].includes(x.category)?x.category:'hardware',unit:['m2','m','piece','module'].includes(x.unit)?x.unit:'piece',rate:x.rate===null||x.rate===''||x.rate===undefined?null:finite(x.rate,0,10000000,null)}));const ids=new Set();for(const c of catalog){if(ids.has(c.id))throw Error('Повтор ID в каталоге');ids.add(c.id);}const assignments={};if(raw?.assignments&&typeof raw.assignments==='object')for(const [id,a] of Object.entries(raw.assignments).slice(0,60)){if(!a||['__proto__','constructor','prototype'].includes(id))continue;assignments[id]={};for(const key of ['body','front','top','labor'])if(ids.has(a[key]))assignments[id][key]=a[key];assignments[id].hardware=(Array.isArray(a.hardware)?a.hardware:[]).slice(0,30).filter(x=>ids.has(x.catalogId)).map(x=>({catalogId:x.catalogId,quantity:finite(x.quantity,0,1000,1)}));}return {catalog,assignments};}
export function estimateProject(p){const b=normalizeBusiness(p.business),items=[],missing=[];for(const m of p.modules.filter(x=>x.visible!==false)){const a=b.assignments[m.id]||{},w=m.width/1000,h=m.height/1000,d=m.depth/1000;const quantities={body:2*h*d+2*w*d+w*h+(m.shelves||0)*w*d,front:w*Math.max(0,h-m.legs/1000-(['base','drawers','sink','oven','island','dresser','bench'].includes(m.type)?m.topThickness/1000:0)),top:w*d,labor:1};for(const type of ['body','front','top','labor']){if(type==='top'&&!['base','drawers','sink','oven','island','dresser','bench'].includes(m.type))continue;if(type==='front'&&m.type==='open')continue;const c=b.catalog.find(c=>c.id===a[type]&&c.category===type);if(!c){missing.push(m.name+': '+({body:'корпус',front:'фасад',top:'столешница',labor:'работа'})[type]);continue;}const quantity=c.unit==='module'||c.unit==='piece'?1:c.unit==='m'?w:quantities[type];items.push({moduleId:m.id,module:m.name,...c,quantity,total:c.rate===null?null:Math.round(quantity*c.rate*100)/100});if(c.rate===null)missing.push(m.name+': цена '+c.name);}for(const ref of a.hardware||[]){const c=b.catalog.find(c=>c.id===ref.catalogId&&c.category==='hardware');if(c){items.push({moduleId:m.id,module:m.name,...c,quantity:ref.quantity,total:c.rate===null?null:ref.quantity*c.rate});if(c.rate===null)missing.push(m.name+': цена '+c.name);}else missing.push(m.name+': назначенная фурнитура удалена или имеет другую категорию');}if(!(a.hardware||[]).length)missing.push(m.name+': фурнитура не назначена');}return {items,missing,subtotal:Math.round(items.reduce((s,x)=>s+(x.total??0),0)*100)/100,complete:missing.length===0};}
export function safeSnapshot(p){const out=structuredClone(p);delete out.versions;if(out.business)delete out.business.versions;return out;}
export function compareProjects(a,b){const changes=[];const old=new Map(a.modules.map(m=>[m.id,m]));for(const m of b.modules){const o=old.get(m.id);if(!o){changes.push('Добавлен: '+m.name);continue;}for(const k of ['width','height','depth','x','y','z','rotation','front','body','top','handle','shelves','drawers','doors','finishClass','edgeColor','frontGap','groupId','frontMaterial','bodyMaterial','topMaterial','handleMaterial','frontRoughness','bodyRoughness','topRoughness','handleRoughness','grainMatch'])if(o[k]!==m[k])changes.push(`${m.name}: ${({width:'ширина',height:'высота',depth:'глубина',rotation:'поворот',front:'фасад',body:'корпус',top:'столешница',handle:'ручка',shelves:'полки',drawers:'ящики',doors:'двери',finishClass:'покрытие',edgeColor:'кромка',frontGap:'зазор фасадов',groupId:'группа'})[k]||k} — ${o[k]} → ${m[k]}`);if(JSON.stringify(o.details)!==JSON.stringify(m.details))changes.push(m.name+': изменены детали');old.delete(m.id);}for(const o of old.values())changes.push('Удалён: '+o.name);if(JSON.stringify(a.room)!==JSON.stringify(b.room))changes.push('Изменено помещение');if(JSON.stringify(a.business)!==JSON.stringify(b.business))changes.push('Изменены каталог или назначения сметы');return changes;}
export async function encodeReviewLink(project,base){const snapshot=safeSnapshot(project);if(snapshot.room.planImage)snapshot.room.planImage=null;const bytes=new TextEncoder().encode(JSON.stringify(snapshot));if(bytes.length>400000)throw Error('Для ссылки проект слишком большой. Передайте JSON.');const stream=new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip')),data=new Uint8Array(await new Response(stream).arrayBuffer());let binary='';for(const b of data)binary+=String.fromCharCode(b);const code=btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');if(code.length>60000)throw Error('Ссылка слишком длинная. Передайте JSON.');return base.split('#')[0]+'#review='+code;}
export async function decodeReviewLink(url){const hash=new URL(url).hash;if(!hash.startsWith('#review='))return null;const code=hash.slice(8);if(code.length>60000||!/^[A-Za-z0-9_-]+$/.test(code))throw Error('Некорректная ссылка проекта');const data=Uint8Array.from(atob(code.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const reader=new Blob([data]).stream().pipeThrough(new DecompressionStream('gzip')).getReader();let total=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;total+=value.length;if(total>500000){await reader.cancel();throw Error('Ссылка превышает допустимый размер проекта');}chunks.push(value);}return JSON.parse(await new Blob(chunks).text());}
